-- 35 more designed frames and 27 more banners for the pearl clam, so every
-- rarity has at least 10 frames and 8 banners. The art lives in the app
-- (AvatarFrame.tsx, BannerArt.tsx, AnimatedBanner.tsx). Legendary banners
-- move on profiles, and the Purring cat frame purrs.
-- Run after 20261120_replies_delete_film_strip.sql. Safe to re-run.

on conflict (id) do update set
  label = excluded.label,
  price = excluded.price,
  is_purchasable = excluded.is_purchasable,
  unlock_hint = excluded.unlock_hint,
  sort_order = excluded.sort_order,
  rarity = excluded.rarity,
  in_blind_box = excluded.in_blind_box,
  box = excluded.box;
